            n.modelId ?? '',
            n.cachedTokens !== undefined ? String(n.cachedTokens) : '',
            n.requiredTokens !== undefined ? String(n.requiredTokens) : ''
        ], n.cause));
        if (n.promptTokens !== undefined)
            this.promptTokens = n.promptTokens;
        if (n.ctxSize !== undefined)
            this.ctxSize = n.ctxSize;
        if (n.modelId !== undefined)
            this.modelId = n.modelId;
        if (n.cachedTokens !== undefined)
            this.cachedTokens = n.cachedTokens;
        if (n.requiredTokens !== undefined)
            this.requiredTokens = n.requiredTokens;
