                    const response = await safeFetch(shard.url, {
                        method: 'HEAD',
                        timeoutMs: connectionTimeout,
                        enforceSecureTransport: shouldEnforceSecureTransport(shard.url, requireSecureTransport),
                        signal: ctx.signal
