            type: 'modelProgress',
            downloaded: overallTotal,
            total: overallTotal,
            percentage: 100,
            downloadKey,
            shardInfo: {
                currentShard: allShards.length,
                totalShards: allShards.length,
                shardName: allShards[allShards.length - 1].shard.filename,
                overallDownloaded: overallTotal,
                overallTotal,
                overallPercentage: 100
