import { generateShortHash, detectShardedModel, getShardedModelCacheDir, getShardPath, extractTensorsFromShards, calculatePercentage } from '../../utils/index.js';
import { getSingleFileCachePath } from '../../utils/cache/paths.js';
import { getModelByPath } from '../../models/registry/index.js';
import { getRegistryClient } from '../../runtime/registry-client.js';
import { createRegistryDownloadKey, startOrJoinDownload, applyJoinedDownloadStats } from './download-manager.js';
import { buildBlobBinding, validateCachedFile, downloadSingleFileFromRegistry } from './registry-download-utils.js';
import { downloadCompanionSetFromRegistry } from './registry-companion-set.js';
import { DownloadCancelledError, ModelNotFoundError, RegistryDownloadFailedError } from '../../errors/index.js';
import { getEngineLogger } from '../../logging/index.js';
